import{_ as t,o as a,c as r,a2 as d}from"./chunks/framework.CDU0sSpB.js";const f=JSON.parse('{"title":"文档地图","description":"Hearth 的文档结构、推荐阅读顺序、维护规则和发布边界。","frontmatter":{"title":"文档地图","description":"Hearth 的文档结构、推荐阅读顺序、维护规则和发布边界。","outline":[2]},"headers":[],"relativePath":"reference/source-map.md","filePath":"reference/source-map.md","lastUpdated":1793890227000}'),h={name:"reference/source-map.md"};function l(o,e,i,s,n,c){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="文档地图" tabindex="-1">文档地图 <a class="header-anchor" href="#文档地图" aria-label="Permalink to &quot;文档地图&quot;">​</a></h1><p class="lead">所有正式文档只在 `docs/` 中维护，仓库和线上站点使用同一份内容。中文是默认路径，英文使用相同结构。找不到某类信息时，可以先从这里确定该读哪一块。</p><h2 id="站点结构" tabindex="-1">站点结构 <a class="header-anchor" href="#站点结构" aria-label="Permalink to &quot;站点结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>内容</th><th>入口</th></tr></thead><tbody><tr><td>开始使用</td><td>本地运行、模型接入、数据与备份、开发与测试</td><td><a href="/hearth-os/guide/">快速开始</a></td></tr><tr><td>产品设计</td><td>1 篇总体设计 + 11 篇模块设计，解释为什么这样设计</td><td><a href="/hearth-os/design/">总体设计</a></td></tr><tr><td>交付路线</td><td>阶段一验收、阶段二至六能力、剩余路线、验收规则</td><td><a href="/hearth-os/delivery/">交付总览</a></td></tr><tr><td>开发日志</td><td>Day01–Day04 的逐日记录、提交明细与边界</td><td><a href="/hearth-os/log/">开发日志</a></td></tr><tr><td>参考</td><td>工程、风险、决策、自研边界、术语、清单和维护资料</td><td><a href="/hearth-os/reference/">参考</a></td></tr><tr><td>站点入口</td><td>首页和双语切换</td><td><a href="/hearth-os/">首页</a></td></tr></tbody></table><p>设计部分按能力组织，不按代码目录组织：入口与交互、任务与持久执行、控制面与授权、执行器与路由、原生 Agent Runtime、审批与外部副作用、运行环境与安全、记忆与能力进化、评估与成本、多设备与长期运行，以及 Agent 参考模式。它们彼此并列，不必按固定顺序阅读。</p><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to &quot;推荐阅读顺序&quot;">​</a></h2><p>第一次了解项目，可以按“为什么做 → 现在有什么 → 还缺什么 → 怎么跑起来”的顺序：</p><ol><li>从<a href="/hearth-os/design/">总体设计</a>理解产品定位、任务链路、技术选型和模块边界；</li><li>看<a href="/hearth-os/delivery/">交付总览</a>确认六个阶段的真实状态，再按需进入<a href="/hearth-os/delivery/mvp.html">阶段一验收</a>或<a href="/hearth-os/delivery/capabilities.html">阶段二至六能力</a>；</li><li>想自己运行，直接看<a href="/hearth-os/guide/">快速开始</a>，需要模型时看<a href="/hearth-os/guide/models.html">接入模型</a>；</li><li>准备继续开发，读<a href="/hearth-os/delivery/roadmap.html">剩余路线</a>、<a href="/hearth-os/delivery/acceptance.html">验收与证据</a>和<a href="/hearth-os/reference/engineering.html">工程实施</a>。</li></ol><p>只想判断项目是否值得继续看，先读总体设计的“产品定位与目标”和交付总览的状态表即可。</p><h2 id="维护与发布规则" tabindex="-1">维护与发布规则 <a class="header-anchor" href="#维护与发布规则" aria-label="Permalink to &quot;维护与发布规则&quot;">​</a></h2><ol><li>先改中文页面，确认结论、边界和链接准确，再在同一次提交中更新英文镜像。</li><li>修改结构、导航或交付路线后，检查附录、侧栏、首页、语言切换和旧链接是否仍然对得上。</li><li>设计说明不引入代码路径、内部类名和实现示例；工程约束留在参考区。</li><li>删除旧页面时直接下线，不保留重定向和重复正文；全站搜索旧路径，避免留下死链。</li><li>运行 <code>npm run docs:build</code>，再检查站内链接、移动端宽度、暗色模式和搜索入口。</li><li>不写“应该”“以后会”来掩盖尚未做出的决定；未验证的内容明确标成假设或留空。</li></ol><p>当前文档描述已经实现的代码闭环、已经取得的验收证据，以及仍未验收的边界。阶段二至六有可运行代码和自动测试，但没有用真实账户、真实设备或长期运行冒充完成。开发日志记录当天的工作和提交，不冒充产品发版说明；只有形成可安装版本后，才维护正式版本号和发布说明。</p><p>线上站点应当与仓库的 <code>docs/</code> 构建结果一致。每次发布后检查旧地址是否已经下线、双语页面是否都能访问、侧栏与首页入口是否指向新结构。</p>',13)])])}const m=t(h,[["render",l]]);export{f as __pageData,m as default};
